{"cmd":"python - <<'PY'
import csv, statistics
from collections import defaultdict
PATH='benchmark/data.csv'
rows=[]
with open(PATH,newline='',encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        rows.append({
            'iso_code': row['iso_code'],
            'country': row['country'],
            'year': int(row['year']),
            'sex': row['sex'],
            'age_group': row['age_group'],
            'homicide_rate': float(row['homicide_rate'])
        })

age_rows=[r for r in rows if r['age_group']!='ALL' and r['sex'] in ('male','female')]
by_age=defaultdict(list)
for r in age_rows:
    by_age[r['age_group']].append(r['homicide_rate'])

age_mean={k: sum(v)/len(v) for k,v in by_age.items()}
print('age groups by mean (all years, both sexes pooled)')
for k,v in sorted(age_mean.items(), key=lambda x:x[1], reverse=True):
    print(k, v, 'n', len(by_age[k]))

# Compare within 2023 by age group and sex
by_age_sex=defaultdict(list)
for r in age_rows:
    if r['year']==2023:
        by_age_sex[(r['age_group'],r['sex'])].append(r['homicide_rate'])

print('\n2023 availability (n rows)')
for k in sorted(by_age_sex):
    print(k, len(by_age_sex[k]))

print('\n2023 medians by age_group for males (if any)')
ages=sorted({a for (a,s) in by_age_sex})
for a in ages:
    m=by_age_sex.get((a,'male'),[])
    if m:
        print(a, 'median', statistics.median(m), 'mean', sum(m)/len(m))
